  ('00000000-0000-4000-8000-000000000005', 'premium-5-bedroom-villa-maitama', 'Premium 5-Bedroom Villa', 'Maitama', 'Abuja', 310000000, 'Villa', 5, 5, 640, array['https://images.unsplash.com/photo-1600607688969-a5bfcd646154?auto=format&fit=crop&w=1600&q=80', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1600&q=80', 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1600&q=80'], true, true, 'A villa in Maitama with double-height reception rooms, a pool, a cinema room and staff quarters.', array['Swimming pool', 'Cinema room', 'Staff quarters', 'Elevator', 'Backup power'], '00000000-0000-4000-9000-000000000005', 'published', now() - interval '4 hours'),
